# fmt: on


def build() -> list[dict]:
    questions: list[dict] = []
    qid = 1
    for difficulty, bank in [("Easy", EASY[:200]), ("Medium", MEDIUM[:200]), ("Hard", HARD[:200])]:
        for q, choices, answer, explanation, tags in bank:
            questions.append(
                {
                    "id": qid,
                    **B,
                    "difficulty": difficulty,
                    "question": q,
                    "choices": choices,
                    "answer": answer,
                    "explanation": explanation,
                    "tags": tags,
                }
            )
            qid += 1
    return questions


if __name__ == "__main__":
    data = build()
    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    OUTPUT.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding="utf-8")
    easy = sum(1 for q in data if q["difficulty"] == "Easy")
    medium = sum(1 for q in data if q["difficulty"] == "Medium")
    hard = sum(1 for q in data if q["difficulty"] == "Hard")
    print(f"Generated {len(data)} questions: {easy} Easy, {medium} Medium, {hard} Hard")
    print(f"Output: {OUTPUT}")
